(()=>{'use strict';
function plan(base={},growth={},work={}){const list=v=>Array.isArray(v)?v:[],products=list(base.products),orders=list(base.orders),partners=list(growth.partners),prospects=list(growth.prospects),evidence=list(base.evidence),tasks=list(work.tasks);const open=orders.filter(o=>!['Delivered','Closed'].includes(o.stage));const add=(area,title,deliverable,target,reason)=>({area,title,deliverable,target,reason});const proposals=[];
if(!String(base.designer?.name||'').trim())proposals.push(add('branding','Define my designer brand','Write my designer name, audience, signature style, brand story and contact details. Review and save my profile.','designer','No designer name saved.'));
if(!products.length)proposals.push(add('products','Prepare a launch collection','Choose one design, record sizes, colours, availability, photographs and all confirmed costs. Set a reviewed selling price.','catalogue','No collection products saved.'));
else proposals.push(add('products','Review collection profitability','Confirm fabric, labour, production, packaging, delivery and other costs for each design. Review prices before accepting orders.','catalogue',products.length+' saved designs to review.'));
if(!evidence.length)proposals.push(add('visibility','Build my visibility evidence','Save my actual website and social profile URLs. Check public access, consistent designer name and missing profile information. Record source and date; do not invent search rankings.','evidence','No visibility evidence links saved.'));
else proposals.push(add('visibility','Check my public visibility','Run the saved-source investigation. Review proof links, access walls and brand mentions. Add dated Search Console or platform evidence for any ranking claim.','evidence',evidence.length+' saved evidence links; search rank has not been measured by this planner.'));
if(open.length){const o=[...open].sort((a,b)=>String(a.due||'9999').localeCompare(String(b.due||'9999')))[0];proposals.push(add('sales','Review next customer action','Review '+String(o.customer||'customer')+' at '+String(o.stage||'Enquiry')+'. '+String(o.nextAction||'Agree consultation, requirements, quote and follow-up. Do not mark paid without payment evidence.'),'orders',open.length+' open customer records.'));}
else proposals.push(add('sales','Prepare my customer consultation','Define ideal customer, budget, measurements, occasion and timing questions. Record genuine enquiries and agree the next action.','prospects','No open customer enquiry saved.'));
proposals.push(add('marketing','Plan a collection campaign','Choose one garment and audience. Create a Studio brief with image/video formats and editable platform captions. Review claims, pricing and permissions before scheduling.','digital-studio','Human review required before publishing.'));
if(!partners.length)proposals.push(add('opportunities','Compare production and sourcing partners','Research fabric, manufacturing, white-label and packaging partners. Save public proof URLs, contacts, quotes, minimum quantities and delivery terms; compare before selecting.','partners','No sourcing partners saved.'));
proposals.push(add('career','Prepare my store launch','Review profile, product details, pricing, enquiry route, fulfilment and delivery terms. Preview the storefront before publishing.','launch','Launch requires reviewed business details.'));
proposals.push(add('skills','Improve my fashion design workflow','Choose one AI-assisted design skill to practise. Record the tool used, experiment, output and lessons; save a reviewed portfolio piece.','my-studio','Learning and creative judgement remain yours.'));
return {proposals:proposals.map(p=>({...p,title:p.title.slice(0,200),deliverable:p.deliverable.slice(0,1000),alreadyQueued:tasks.some(t=>!t.done&&t.title===p.title)})),facts:{designs:products.length,openOrders:open.length,prospects:prospects.length,suppliers:partners.length,evidence:evidence.length,openTasks:tasks.filter(t=>!t.done).length},notice:'Plan derived from saved records. No live search rank, buyer intent, sales outcome or autonomous AI action is implied.'};}
window.bongaFashionPlanner={plan};const root=document.getElementById('fashion-command');if(!root)return;let current,lastRecords='';const el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};const read=k=>{try{return JSON.parse(localStorage.getItem(k))||{};}catch{return {};}};
function render(force=false){const records=[read('zuxuru-fashion-service-v1'),read('zuxuru-fashion-growth-v1'),read('zuxuru-designer-work-v1')],signature=JSON.stringify(records);if(!force&&signature===lastRecords)return;lastRecords=signature;current=plan(...records);const box=document.getElementById('fashion-plan-cards');box.replaceChildren();document.getElementById('fashion-plan-summary').textContent=current.facts.designs+' designs · '+current.facts.openOrders+' open customers · '+current.facts.prospects+' prospects · '+current.facts.openTasks+' open tasks';for(const p of current.proposals){const card=el('article');card.className='record';card.append(el('h3',p.title),el('p',p.reason),el('p',p.deliverable));const link=el('a','Open work area');link.href='#'+p.target;const button=el('button',p.alreadyQueued?'Already in my work':'Review task');button.type='button';button.disabled=p.alreadyQueued;button.onclick=()=>{const form=document.getElementById('designer-task-form');if(['title','deliverable','due'].some(k=>form.elements.namedItem(k).value)&&!confirm('Replace the unsaved task brief?'))return;delete form.dataset.sourceOrderId;form.elements.namedItem('area').value=p.area;form.elements.namedItem('title').value=p.title;form.elements.namedItem('deliverable').value=p.deliverable;form.elements.namedItem('due').value='';location.hash='my-work';form.scrollIntoView({behavior:'auto'});form.elements.namedItem('title').focus();document.getElementById('designer-work-status').textContent='Review this proposed task and choose Add to my work. No action has run.';};card.append(link,button);box.append(card);}document.getElementById('fashion-plan-status').textContent=current.notice;}
document.getElementById('fashion-plan-refresh').onclick=()=>render(true);document.getElementById('fashion-plan-download').onclick=()=>{render();const text=['BONGA BHENGU · FASHION BUSINESS PLAN',new Date().toISOString(),current.notice,...current.proposals.flatMap((p,i)=>['',String(i+1)+'. '+p.title,p.reason,p.deliverable])].join('\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain'}));const a=el('a');a.href=url;a.download='bonga-fashion-business-plan.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};window.addEventListener('storage',()=>render());setInterval(()=>{if(!document.hidden)render();},2000);render();
})();
